    <div class="status-bar-container">
        <!-- 粒子特效背景 -->
        <div class="particles-container" id="particles"></div>

        <!-- 状态栏主体 -->
        <div class="status-bar">
            <!-- 状态栏标题 -->
            <div class="status-header">
                <h1 class="status-title">PRIVACY DEVELOPMENT STATUS</h1>
                <p class="status-subtitle">"隐私层次决定社会权限 · 监控等级划分个体维度"</p>
            </div>

            <!-- 角色列表容器 -->
            <div class="characters-list" id="charactersList">
                <!-- 角色行将通过JavaScript动态生成 -->
            </div>
        </div>
    </div>

    <script>
        // 生成金色尘埃背景
        function createParticles() {
            const container = document.getElementById('particles');
            const count = 18;
            for(let i = 0; i < count; i++) {
                const p = document.createElement('div');
                p.classList.add('particle');
                const size = Math.random() * 3 + 1 + 'px';
                p.style.width = size;
                p.style.height = size;
                p.style.left = Math.random() * 100 + '%';
                p.style.animationDuration = Math.random() * 20 + 10 + 's';
                p.style.animationDelay = Math.random() * 10 + 's';
                p.style.opacity = Math.random() * 0.4;
                container.appendChild(p);
            }
        }

        // 隐私等级描述映射
        const privacyLevelDescriptions = {
            1: "I级 · 基础档案公开",
            2: "II级 · 轨迹追踪", 
            3: "III级 · 公共监控接入",
            4: "IV级 · 住所互联",
            5: "V级 · 完全透明"
        };

        // 中文数字转阿拉伯数字映射
        const chineseToArabic = {
            '一': 1, '壹': 1,
            '二': 2, '贰': 2, '两': 2,
            '三': 3, '叁': 3,
            '四': 4, '肆': 4,
            '五': 5, '伍': 5,
            '六': 6, '陆': 6,
            '七': 7, '柒': 7,
            '八': 8, '捌': 8,
            '九': 9, '玖': 9,
            '十': 10, '拾': 10
        };

        // 将等级字符串转换为数字
        function convertLevelToNumber(levelStr) {
            // 去除可能的中文"级"字
            levelStr = levelStr.replace(/级$/, '');

            // 如果已经是数字，直接转换
            if (!isNaN(levelStr)) {
                const num = parseInt(levelStr);
                if (num >= 1 && num <= 5) return num;
            }

            // 如果是中文数字，尝试转换
            if (chineseToArabic[levelStr] !== undefined) {
                const num = chineseToArabic[levelStr];
                if (num >= 1 && num <= 5) return num;
            }

            // 如果都不匹配，返回null表示无法识别
            return null;
        }

        // 使用正则表达式从输入数据中提取内容
        function extractDataWithRegex(inputData) {
            const regex = /<item>([\s\S]*?)<\/item>/g;
            const matches = [];
            let match;

            // 提取所有匹配项
            while ((match = regex.exec(inputData)) !== null) {
                matches.push(match[1].trim());
            }

            // 如果有匹配项，返回第一个匹配的内容
            if (matches.length > 0) {
                return matches[0];
            }

            // 如果没有匹配项，返回原始输入
            return inputData;
        }

        // 解析角色数据字符串
        function parseCharacterData(dataString) {
            // 首先使用正则提取<item>标签内的内容
            const extractedContent = extractDataWithRegex(dataString);

            // 改进的正则表达式：支持"角色名|等级"格式，等级可以是数字、中文或任意文本
            // 使用换行符分割不同角色，每行格式：角色名|等级
            const lines = extractedContent.split('\n');
            const characters = [];

            for (let line of lines) {
                line = line.trim();
                if (!line) continue; // 跳过空行

                // 匹配"角色名|等级"格式
                const match = line.match(/^(.+?)\|(.+)$/);
                if (match) {
                    const name = match[1].trim();
                    const levelStr = match[2].trim();

                    // 尝试将等级转换为数字
                    const level = convertLevelToNumber(levelStr);

                    // 如果成功转换为1-5的数字
                    if (level !== null && level >= 1 && level <= 5) {
                        characters.push({ name, level, levelStr });
                    } else {
                        // 无法识别的等级，直接使用原字符串
                        characters.push({ name, level: null, levelStr });
                    }
                }
            }

            return characters;
        }

        // 生成角色行HTML
        function createCharacterRow(character, index) {
            // 确定隐私标签的显示内容
            let privacyText;
            let levelClass = "level-unknown";

            if (character.level !== null && character.level >= 1 && character.level <= 5) {
                // 有效等级，显示对应描述
                privacyText = privacyLevelDescriptions[character.level];
                levelClass = `level-${character.level}`;
            } else {
                // 无法识别的等级，直接显示原字符串
                privacyText = character.levelStr;
            }

            return `
                <div class="character-row">
                    <div class="character-name-container">
                        <div class="character-name">${character.name}</div>
                        <div class="privacy-label ${levelClass}">
                            ${privacyText}
                        </div>
                    </div>
                </div>
            `;
        }

        // 更新状态栏显示
        function updateStatusBar(characters) {
            const container = document.getElementById('charactersList');

            if (!characters || characters.length === 0) {
                container.innerHTML = `
                    <div class="empty-state">
                        <p>未检测到角色数据</p>
                        <p>等待数据流接入...</p>
                    </div>
                `;
                return;
            }

            container.innerHTML = '';

            characters.forEach((character, index) => {
                const rowHTML = createCharacterRow(character, index);
                container.innerHTML += rowHTML;
            });
        }

        // 使用正则提取并解析数据
        function loadDataWithRegex() {
            // 这里可以替换为您的实际数据源
            const inputData = `<item>
$1
</item>`;

            return parseCharacterData(inputData);
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            createParticles();

            // 模拟数据加载延迟
            setTimeout(() => {
                const characters = loadDataWithRegex();
                updateStatusBar(characters);
            }, 800);
        });

        // 外部调用函数：用于从外部注入数据
        window.updateCharactersFromData = function(dataString) {
            const characters = parseCharacterData(dataString);
            updateStatusBar(characters);
            return characters.length; // 返回解析到的角色数量
        };

        // 外部调用函数：直接使用正则匹配并更新
        window.updateCharactersWithRegex = function(inputData) {
            // 使用正则提取<item>标签内容
            const extractedData = extractDataWithRegex(inputData);
            const characters = parseCharacterData(extractedData);
            updateStatusBar(characters);
            return characters.length;
        };

        // 测试函数：验证不同的数据格式
        window.testVariousFormats = function() {
            const testData = [
                "Mark|未知",
                "张三|三",
                "李四|IV",  // 罗马数字，不会被识别
                "王五|5",
                "赵六|二",
                "测试|一级", // 带"级"字
                "测试2|1级",
                "测试3|十",  // 超出1-5范围
                "测试4|六"   // 超出1-5范围
            ].join('\n');

            const wrappedData = `<item>${testData}</item>`;
            return window.updateCharactersWithRegex(wrappedData);
        };
    </script>
